from bioblend.galaxy import GalaxyInstance
import os, time

api_key = open(os.environ.get('GALAXY_API_KEY_FILE','/claude_home/.galaxy/api_key')).read().strip()
gi = GalaxyInstance('https://usegalaxy.org', key=api_key)
hist_id = 'bbd44e69cb8906b562d7cc479eefc75f'

# Use Table Compute with fulltable custom mode to filter
# table is the pandas DataFrame
# Keep rows where the last column (gene_biotype) equals 'protein_coding'
expr = \"table[table.iloc[:,-1] == 'protein_coding']\"

inputs = {
    'singtabop': {
        'use_type': 'single',
        'input': {'src': 'hda', 'id': 'f9cad7b01a472135d6de7b4933635ca9'},
        'col_row_names': 'has_col_names',
        'user': {
            'mode': 'fulltable',
            'general': {
                'use': 'custom',
                'fulltable_custom_expr': expr
            }
        }
    }
}

print(f'Expression: {expr}')
result = gi.tools.run_tool(
    history_id=hist_id,
    tool_id='toolshed.g2.bx.psu.edu/repos/iuc/table_compute/table_compute/1.2.4+galaxy2',
    tool_inputs=inputs
)
for out in result.get('outputs', []):
    print(f\"  HID {out['hid']}: {out['name']} ({out['state']})\")
for job in result.get('jobs', []):
    print(f\"  Job: {job['id']}\")
    job_id = job['id']
"

